import React, { useState, useEffect } from 'react';
import { Link, withPrefix } from 'gatsby';
import PropTypes from 'prop-types';
import { CSSTransition, TransitionGroup } from 'react-transition-group';
import styled, { css } from 'styled-components';
import { navLinks } from '@config';
import { loaderDelay } from '@utils';
import { useScrollDirection, usePrefersReducedMotion } from '@hooks';
import { Menu } from '@components';
import { IconLogo, IconHex } from '@components/icons';

const scrollUpStyles = ({ scrollDirection, scrolledToTop }) =>
  scrollDirection === 'up' &&
  !scrolledToTop &&
  css`
    height: var(--nav-scroll-height);
    transform: translateY(0px);
    background-color: var(--nav-bg);
    box-shadow: 0 10px 30px -10px var(--navy-shadow);
  `;

const scrollDownStyles = ({ scrollDirection, scrolledToTop }) =>
  scrollDirection === 'down' &&
  !scrolledToTop &&
  css`
    height: var(--nav-scroll-height);
    transform: translateY(calc(var(--nav-scroll-height) * -1));
    box-shadow: 0 10px 30px -10px var(--navy-shadow);
  `;

const getToggleThumbShadow = ({ $isLightMode }) =>
  $isLightMode
    ? 'inset -2px -3px 4px rgba(2, 12, 27, 0.08), 0 0 0 2px rgba(230, 241, 255, 0.22)'
    : 'inset -7px -3px 0 -2px #fff7a8, 0 0 0 2px rgba(255, 230, 0, 0.18)';

const StyledHeader = styled.header`
  ${({ theme }) => theme.mixins.flexBetween};
  position: fixed;
  top: 0;
  z-index: 11;
  padding: 0px 50px;
  width: 100%;
  height: var(--nav-height);
  background-color: var(--nav-bg);
  filter: none !important;
  pointer-events: auto !important;
  user-select: auto !important;
  backdrop-filter: blur(10px);
  transition: var(--transition);

  @media (max-width: 1080px) {
    padding: 0 40px;
  }
  @media (max-width: 768px) {
    padding: 0 25px;
  }

  @media (prefers-reduced-motion: no-preference) {
    ${scrollUpStyles};
    ${scrollDownStyles};
  }
`;

const StyledNav = styled.nav`
  ${({ theme }) => theme.mixins.flexBetween};
  position: relative;
  width: 100%;
  color: var(--lightest-slate);
  font-family: var(--font-mono);
  counter-reset: item 0;
  z-index: 12;

  .logo {
    ${({ theme }) => theme.mixins.flexCenter};

    a {
      color: var(--green);
      width: 42px;
      height: 42px;
      position: relative;
      z-index: 1;

      .hex-container {
        position: absolute;
        top: 0;
        left: 0;
        z-index: -1;
        @media (prefers-reduced-motion: no-preference) {
          transition: var(--transition);
        }
      }

      .logo-container {
        position: relative;
        z-index: 1;
        svg {
          fill: none;
          user-select: none;
          @media (prefers-reduced-motion: no-preference) {
            transition: var(--transition);
          }
          polygon {
            fill: var(--navy);
          }
        }
      }

      &:hover,
      &:focus {
        outline: 0;
        transform: translate(-4px, -4px);
        .hex-container {
          transform: translate(4px, 3px);
        }
      }
    }
  }
`;

const StyledLinks = styled.div`
  display: flex;
  align-items: center;

  @media (max-width: 768px) {
    display: none;
  }

  ol {
    ${({ theme }) => theme.mixins.flexBetween};
    padding: 0;
    margin: 0;
    list-style: none;

    li {
      margin: 0 5px;
      position: relative;
      counter-increment: item 1;
      font-size: var(--fz-xs);

      a {
        padding: 10px;

        &:before {
          content: '0' counter(item) '.';
          margin-right: 5px;
          color: var(--green);
          font-size: var(--fz-xxs);
          text-align: right;
        }
      }
    }
  }

  .resume-button {
    ${({ theme }) => theme.mixins.smallButton};
    margin-left: 15px;
    font-size: var(--fz-xs);
  }
`;

const StyledThemeToggle = styled.button`
  ${({ theme }) => theme.mixins.flexCenter};
  position: relative;
  width: 64px;
  height: 34px;
  padding: 0;
  margin-left: 15px;
  border: 3px solid var(--white);
  border-radius: 999px;
  background: ${({ $isLightMode }) => ($isLightMode ? 'var(--light-navy)' : '#06131a')};
  box-shadow: 0 6px 18px -8px var(--navy-shadow);
  transition: var(--transition);
  overflow: hidden;

  @media (max-width: 768px) {
    margin: 22px auto 0;
  }

  &:hover,
  &:focus {
    transform: translateY(-2px);
    box-shadow: 0 10px 22px -10px var(--navy-shadow);
  }

  .toggle-thumb {
    position: absolute;
    top: 3px;
    left: 3px;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: ${({ $isLightMode }) => ($isLightMode ? 'var(--white)' : '#ffe600')};
    box-shadow: ${getToggleThumbShadow};
    transform: translateX(${({ $isLightMode }) => ($isLightMode ? '0' : '30px')});
    transition:
      transform 0.25s var(--easing),
      background-color 0.25s var(--easing),
      box-shadow 0.25s var(--easing);
  }

  .toggle-star {
    position: absolute;
    width: 3px;
    height: 3px;
    border-radius: 50%;
    background: #ffe600;
    opacity: ${({ $isLightMode }) => ($isLightMode ? 0.15 : 1)};
    transition: opacity 0.25s var(--easing);
  }

  .toggle-star.one {
    top: 10px;
    right: 27px;
  }

  .toggle-star.two {
    top: 16px;
    right: 19px;
  }

  .toggle-star.three {
    top: 20px;
    right: 33px;
    width: 5px;
    height: 5px;
  }
`;

const Nav = ({ isHome }) => {
  const [isMounted, setIsMounted] = useState(!isHome);
  const scrollDirection = useScrollDirection('down');
  const [scrolledToTop, setScrolledToTop] = useState(true);
  const prefersReducedMotion = usePrefersReducedMotion();
  const [isLightMode, setIsLightMode] = useState(false);

  useEffect(() => {
    const storedTheme = window.localStorage.getItem('theme');
    if (storedTheme === 'light') {
      setIsLightMode(true);
      document.documentElement.classList.add('light-mode');
    }
  }, []);

  const toggleTheme = () => {
    if (isLightMode) {
      setIsLightMode(false);
      document.documentElement.classList.remove('light-mode');
      window.localStorage.setItem('theme', 'dark');
    } else {
      setIsLightMode(true);
      document.documentElement.classList.add('light-mode');
      window.localStorage.setItem('theme', 'light');
    }
  };

  const handleScroll = () => {
    setScrolledToTop(window.pageYOffset < 50);
  };

  useEffect(() => {
    if (prefersReducedMotion) {
      return;
    }

    const timeout = setTimeout(() => {
      setIsMounted(true);
    }, 100);

    window.addEventListener('scroll', handleScroll);

    return () => {
      clearTimeout(timeout);
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  const timeout = isHome ? loaderDelay : 0;
  const fadeClass = isHome ? 'fade' : '';
  const fadeDownClass = isHome ? 'fadedown' : '';

  const Logo = (
    <div className="logo" tabIndex="-1">
      {isHome ? (
        <a href={withPrefix('/')} aria-label="home">
          <div className="hex-container">
            <IconHex />
          </div>
          <div className="logo-container">
            <IconLogo />
          </div>
        </a>
      ) : (
        <Link to="/" aria-label="home">
          <div className="hex-container">
            <IconHex />
          </div>
          <div className="logo-container">
            <IconLogo />
          </div>
        </Link>
      )}
    </div>
  );

  const ResumeLink = (
    <a
      className="resume-button"
      href={withPrefix('/resume.pdf')}
      target="_blank"
      rel="noopener noreferrer">
      Resume
    </a>
  );

  const renderThemeToggle = () => (
    <StyledThemeToggle
      onClick={toggleTheme}
      aria-label={isLightMode ? 'Switch to dark mode' : 'Switch to light mode'}
      aria-pressed={isLightMode}
      $isLightMode={isLightMode}>
      <span className="toggle-thumb" aria-hidden="true" />
      <span className="toggle-star one" aria-hidden="true" />
      <span className="toggle-star two" aria-hidden="true" />
      <span className="toggle-star three" aria-hidden="true" />
    </StyledThemeToggle>
  );

  return (
    <StyledHeader scrollDirection={scrollDirection} scrolledToTop={scrolledToTop}>
      <StyledNav>
        {prefersReducedMotion ? (
          <>
            {Logo}

            <StyledLinks>
              <ol>
                {navLinks &&
                  navLinks.map(({ url, name }, i) => (
                    <li key={i}>
                      <Link to={url}>{name}</Link>
                    </li>
                  ))}
              </ol>
              <div style={{ display: 'flex', alignItems: 'center' }}>
                {ResumeLink}
                {renderThemeToggle()}
              </div>
            </StyledLinks>

            <Menu themeToggle={renderThemeToggle()} />
          </>
        ) : (
          <>
            <TransitionGroup component={null}>
              {isMounted && (
                <CSSTransition classNames={fadeClass} timeout={timeout}>
                  <>{Logo}</>
                </CSSTransition>
              )}
            </TransitionGroup>

            <StyledLinks>
              <ol>
                <TransitionGroup component={null}>
                  {isMounted &&
                    navLinks &&
                    navLinks.map(({ url, name }, i) => (
                      <CSSTransition key={i} classNames={fadeDownClass} timeout={timeout}>
                        <li key={i} style={{ transitionDelay: `${isHome ? i * 100 : 0}ms` }}>
                          <Link to={url}>{name}</Link>
                        </li>
                      </CSSTransition>
                    ))}
                </TransitionGroup>
              </ol>

              <TransitionGroup component={null}>
                {isMounted && (
                  <CSSTransition classNames={fadeDownClass} timeout={timeout}>
                    <div
                      style={{
                        transitionDelay: `${isHome ? navLinks.length * 100 : 0}ms`,
                        display: 'flex',
                        alignItems: 'center',
                      }}>
                      {ResumeLink}
                      {renderThemeToggle()}
                    </div>
                  </CSSTransition>
                )}
              </TransitionGroup>
            </StyledLinks>

            <TransitionGroup component={null}>
              {isMounted && (
                <CSSTransition classNames={fadeClass} timeout={timeout}>
                  <Menu themeToggle={renderThemeToggle()} />
                </CSSTransition>
              )}
            </TransitionGroup>
          </>
        )}
      </StyledNav>
    </StyledHeader>
  );
};

Nav.propTypes = {
  isHome: PropTypes.bool,
};

export default Nav;
